SELECT "t2"."line_id", "t2"."qty_ok", "t2"."qty_bad", "t2"."last_received", 'complete' AS "route", 'receipts' AS "context"
FROM (SELECT "t"."line_id", COALESCE(SUM(CASE WHEN "p_3fc03684"."condition" = 'ok' THEN "p_3fc03684"."quantity" ELSE 0 END), 0) AS "qty_ok", COALESCE(SUM(CASE WHEN "p_3fc03684"."condition" <> 'ok' THEN "p_3fc03684"."quantity" ELSE 0 END), 0) AS "qty_bad", MAX("p_3fc03684"."received_date") AS "last_received"
        FROM (SELECT "p_ff40000e"."line_id", "p_ff40000e"."request_number", "p_ff40000e"."item", "p_ff40000e"."quantity", "p_ff40000e"."way", "p_ff40000e"."customer0" AS "customer", "p_7d39f2a5"."id" AS "obligation_id", "p_7d39f2a5"."due", "p_7d39f2a5"."state" AS "obligation_state"
                FROM "p_ff40000e"
                    INNER JOIN "p_7d39f2a5" ON "p_7d39f2a5"."entity" = 'return_request_line' AND "p_7d39f2a5"."key" = CAST("p_ff40000e"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a5"."kind" = 'inbound' AND "p_7d39f2a5"."state" IN ('open', 'overdue', 'reopened')) AS "t"
            LEFT JOIN "p_3fc03684" ON "t"."line_id" = "p_3fc03684"."line_id"
        GROUP BY "t"."line_id") AS "t2"
    INNER JOIN (SELECT "line_id"
        FROM (SELECT "t17"."line_id", "t17"."request_number", "t17"."item", "t17"."quantity", "t17"."way", "t17"."customer", "t17"."obligation_id", "t17"."due", "t17"."obligation_state", "t17"."qty_ok", "t17"."qty_bad", "t17"."last_received", "t17"."days_open", "t19"."reminders", CASE WHEN "t17"."qty_ok" >= "t17"."quantity" THEN 'complete' WHEN "t17"."qty_bad" > 0 OR "t17"."qty_ok" > 0 AND "t17"."qty_ok" < "t17"."quantity" THEN 'damaged' WHEN "t17"."days_open" > :inbound_close THEN 'expired' WHEN "t17"."days_open" > :inbound_reminder AND "t19"."reminders" = 0 THEN 'remind' ELSE NULL END AS "route"
                FROM (SELECT "t8"."line_id", "t8"."request_number", "t8"."item", "t8"."quantity", "t8"."way", "t8"."customer", "t8"."obligation_id", "t8"."due", "t8"."obligation_state", "t8"."qty_ok", "t8"."qty_bad", "t8"."last_received", "t16"."days_open"
                        FROM (SELECT "t3"."line_id", "t3"."request_number", "t3"."item", "t3"."quantity", "t3"."way", "t3"."customer", "t3"."obligation_id", "t3"."due", "t3"."obligation_state", "t7"."qty_ok", "t7"."qty_bad", "t7"."last_received"
                                FROM (SELECT "p_ff40000e0"."line_id", "p_ff40000e0"."request_number", "p_ff40000e0"."item", "p_ff40000e0"."quantity", "p_ff40000e0"."way", "p_ff40000e0"."customer0" AS "customer", "p_7d39f2a50"."id" AS "obligation_id", "p_7d39f2a50"."due", "p_7d39f2a50"."state" AS "obligation_state"
                                        FROM "p_ff40000e" AS "p_ff40000e0"
                                            INNER JOIN "p_7d39f2a5" AS "p_7d39f2a50" ON "p_7d39f2a50"."entity" = 'return_request_line' AND "p_7d39f2a50"."key" = CAST("p_ff40000e0"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a50"."kind" = 'inbound' AND "p_7d39f2a50"."state" IN ('open', 'overdue', 'reopened')) AS "t3"
                                    LEFT JOIN (SELECT "t4"."line_id", COALESCE(SUM(CASE WHEN "p_3fc036840"."condition" = 'ok' THEN "p_3fc036840"."quantity" ELSE 0 END), 0) AS "qty_ok", COALESCE(SUM(CASE WHEN "p_3fc036840"."condition" <> 'ok' THEN "p_3fc036840"."quantity" ELSE 0 END), 0) AS "qty_bad", MAX("p_3fc036840"."received_date") AS "last_received"
                                        FROM (SELECT "p_ff40000e1"."line_id", "p_ff40000e1"."request_number", "p_ff40000e1"."item", "p_ff40000e1"."quantity", "p_ff40000e1"."way", "p_ff40000e1"."customer0" AS "customer", "p_7d39f2a51"."id" AS "obligation_id", "p_7d39f2a51"."due", "p_7d39f2a51"."state" AS "obligation_state"
                                                FROM "p_ff40000e" AS "p_ff40000e1"
                                                    INNER JOIN "p_7d39f2a5" AS "p_7d39f2a51" ON "p_7d39f2a51"."entity" = 'return_request_line' AND "p_7d39f2a51"."key" = CAST("p_ff40000e1"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a51"."kind" = 'inbound' AND "p_7d39f2a51"."state" IN ('open', 'overdue', 'reopened')) AS "t4"
                                            LEFT JOIN "p_3fc03684" AS "p_3fc036840" ON "t4"."line_id" = "p_3fc036840"."line_id"
                                        GROUP BY "t4"."line_id") AS "t7" ON "t3"."line_id" = "t7"."line_id") AS "t8"
                            LEFT JOIN (SELECT "t10"."line_id", CASE WHEN "t10"."_ttrp_a_n15_0" IS NULL THEN NULL ELSE COALESCE("t15"."_ttrp_n_n15_0", 0) END AS "days_open"
                                FROM (SELECT "t9"."line_id", "t9"."request_number", "t9"."item", "t9"."quantity", "t9"."way", "t9"."customer", "t9"."obligation_id", "t9"."due", "t9"."obligation_state", "p_f7cce9af"."recipe", "p_f7cce9af"."run", "p_f7cce9af"."entity", "p_f7cce9af"."key", "p_f7cce9af"."kind", "p_f7cce9af"."due" AS "due0", "p_f7cce9af"."state", "p_f7cce9af"."fulfilled_by", "p_f7cce9af"."fulfilled_at", "p_f7cce9af"."created_at", "p_f7cce9af"."created_at" AS "_ttrp_a_n15_0"
                                        FROM (SELECT "p_ff40000e2"."line_id", "p_ff40000e2"."request_number", "p_ff40000e2"."item", "p_ff40000e2"."quantity", "p_ff40000e2"."way", "p_ff40000e2"."customer0" AS "customer", "p_7d39f2a52"."id" AS "obligation_id", "p_7d39f2a52"."due", "p_7d39f2a52"."state" AS "obligation_state"
                                                FROM "p_ff40000e" AS "p_ff40000e2"
                                                    INNER JOIN "p_7d39f2a5" AS "p_7d39f2a52" ON "p_7d39f2a52"."entity" = 'return_request_line' AND "p_7d39f2a52"."key" = CAST("p_ff40000e2"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a52"."kind" = 'inbound' AND "p_7d39f2a52"."state" IN ('open', 'overdue', 'reopened')) AS "t9"
                                            INNER JOIN "p_f7cce9af" ON "t9"."obligation_id" = "p_f7cce9af"."id") AS "t10"
                                    LEFT JOIN (SELECT "t13"."_ttrp_a_n15_0" AS "_ttrp_k_n15_0__ttrp_a_n15_0", COUNT("p_58e569ee"."_ttrp_d_n15_0") AS "_ttrp_n_n15_0"
                                        FROM (SELECT "p_f7cce9af0"."created_at" AS "_ttrp_a_n15_0"
                                                FROM (SELECT "p_ff40000e3"."line_id", "p_ff40000e3"."request_number", "p_ff40000e3"."item", "p_ff40000e3"."quantity", "p_ff40000e3"."way", "p_ff40000e3"."customer0" AS "customer", "p_7d39f2a53"."id" AS "obligation_id", "p_7d39f2a53"."due", "p_7d39f2a53"."state" AS "obligation_state"
                                                        FROM "p_ff40000e" AS "p_ff40000e3"
                                                            INNER JOIN "p_7d39f2a5" AS "p_7d39f2a53" ON "p_7d39f2a53"."entity" = 'return_request_line' AND "p_7d39f2a53"."key" = CAST("p_ff40000e3"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a53"."kind" = 'inbound' AND "p_7d39f2a53"."state" IN ('open', 'overdue', 'reopened')) AS "t11"
                                                    INNER JOIN "p_f7cce9af" AS "p_f7cce9af0" ON "t11"."obligation_id" = "p_f7cce9af0"."id"
                                                GROUP BY "p_f7cce9af0"."created_at") AS "t13"
                                            INNER JOIN "p_58e569ee" ON "t13"."_ttrp_a_n15_0" < "p_58e569ee"."_ttrp_d_n15_0" AND "p_58e569ee"."_ttrp_d_n15_0" <= :as_of
                                        GROUP BY "t13"."_ttrp_a_n15_0") AS "t15" ON "t10"."_ttrp_a_n15_0" = "t15"."_ttrp_k_n15_0__ttrp_a_n15_0") AS "t16" ON "t8"."line_id" = "t16"."line_id") AS "t17"
                    LEFT JOIN (SELECT "t18"."line_id", COUNT("p_4fd248ed"."run") AS "reminders"
                        FROM (SELECT "p_ff40000e4"."line_id", "p_ff40000e4"."request_number", "p_ff40000e4"."item", "p_ff40000e4"."quantity", "p_ff40000e4"."way", "p_ff40000e4"."customer0" AS "customer", "p_7d39f2a54"."id" AS "obligation_id", "p_7d39f2a54"."due", "p_7d39f2a54"."state" AS "obligation_state"
                                FROM "p_ff40000e" AS "p_ff40000e4"
                                    INNER JOIN "p_7d39f2a5" AS "p_7d39f2a54" ON "p_7d39f2a54"."entity" = 'return_request_line' AND "p_7d39f2a54"."key" = CAST("p_ff40000e4"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a54"."kind" = 'inbound' AND "p_7d39f2a54"."state" IN ('open', 'overdue', 'reopened')) AS "t18"
                            LEFT JOIN "p_4fd248ed" ON "t18"."line_id" = "p_4fd248ed"."line_id" AND "p_4fd248ed"."route" = 'remind'
                        GROUP BY "t18"."line_id") AS "t19" ON "t17"."line_id" = "t19"."line_id") AS "t20"
        WHERE "t20"."route" = 'complete'
        GROUP BY "line_id") AS "t23" ON "t2"."line_id" = "t23"."line_id"
